CREATE TRIGGER "client_automation_profiles_dns_shape_on_insert" BEFORE INSERT ON "client_automation_profiles" WHEN NEW."dns_verified_at" IS NOT NULL BEGIN
SELECT RAISE (ABORT, 'dns_verified_at must be an ISO-8601 instant such as 2026-08-20T12:00:00.000Z - a note is not a verification and must never unlock sending from a client domain') WHERE NEW."dns_verified_at" NOT GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*';
END

