END

CREATE TRIGGER "client_automation_profiles_identity_pairing_on_insert" BEFORE INSERT ON "client_automation_profiles" WHEN NEW."reply_identity_mode" IS NOT NULL BEGIN
SELECT RAISE (ABORT, 'reply_from_identity must be one bare mailbox such as support@oasisai.work - no display name, no second address') WHERE length (lower (trim (NEW."reply_from_identity"))) - length (REPLACE (lower (trim (NEW."reply_from_identity")), '@', '')) <> 1;
SELECT RAISE (ABORT, 'shared_oasis and per_client_subaddress must send from an address on oasisai.work - OASIS cannot send as a domain it does not control') WHERE NEW."reply_identity_mode" IN ('shared_oasis', 'per_client_subaddress') AND NOT (length (lower (trim (NEW."reply_from_identity"))) > 13 AND substr (lower (trim (NEW."reply_from_identity")), length (lower (trim (NEW."reply_from_identity"))) - 12) IN ('@oasisai.work', '.oasisai.work'));
SELECT RAISE (ABORT, 'shared_oasis must not carry a plus tag - a tagged address is per_client_subaddress, and filing it as shared reports one shared reputation for a client that has its own analytics lane') WHERE NEW."reply_identity_mode" = 'shared_oasis' AND substr (lower (trim (NEW."reply_from_identity")), 1, instr (lower (trim (NEW."reply_from_identity")), '@') - 1) LIKE '%+%';
SELECT RAISE (ABORT, 'per_client_subaddress needs a non-empty plus tag identifying the client, such as support+acmehvac@oasisai.work - without one every client lands in the same undifferentiated stream') WHERE NEW."reply_identity_mode" = 'per_client_subaddress' AND substr (lower (trim (NEW."reply_from_identity")), 1, instr (lower (trim (NEW."reply_from_identity")), '@') - 1) NOT LIKE '%+_%';
SELECT RAISE (ABORT, 'per_client_domain must send from the client own domain, not from oasisai.work - an OASIS address gets none of the reputation isolation this mode is chosen for') WHERE NEW."reply_identity_mode" = 'per_client_domain' AND length (lower (trim (NEW."reply_from_identity"))) > 13 AND substr (lower (trim (NEW."reply_from_identity")), length (lower (trim (NEW."reply_from_identity"))) - 12) IN ('@oasisai.work', '.oasisai.work');
SELECT RAISE (ABORT, 'per_client_domain must send from this profile own website_domain - sending as a third party domain fails SPF alignment and borrows a reputation nobody granted') WHERE NEW."reply_identity_mode" = 'per_client_domain' AND NOT (length (lower (trim (NEW."reply_from_identity"))) > length (lower (trim (NEW."website_domain"))) + 1 AND substr (lower (trim (NEW."reply_from_identity")), length (lower (trim (NEW."reply_from_identity"))) - length (lower (trim (NEW."website_domain")))) IN ('@' || lower (trim (NEW."website_domain")), '.' || lower (trim (NEW."website_domain"))));
END

CREATE TRIGGER "client_automation_profiles_identity_pairing_on_update" BEFORE UPDATE ON "client_automation_profiles" WHEN NEW."reply_identity_mode" IS NOT NULL BEGIN
SELECT RAISE (ABORT, 'reply_from_identity must be one bare mailbox such as support@oasisai.work - no display name, no second address') WHERE length (lower (trim (NEW."reply_from_identity"))) - length (REPLACE (lower (trim (NEW."reply_from_identity")), '@', '')) <> 1;
SELECT RAISE (ABORT, 'shared_oasis and per_client_subaddress must send from an address on oasisai.work - OASIS cannot send as a domain it does not control') WHERE NEW."reply_identity_mode" IN ('shared_oasis', 'per_client_subaddress') AND NOT (length (lower (trim (NEW."reply_from_identity"))) > 13 AND substr (lower (trim (NEW."reply_from_identity")), length (lower (trim (NEW."reply_from_identity"))) - 12) IN ('@oasisai.work', '.oasisai.work'));
SELECT RAISE (ABORT, 'shared_oasis must not carry a plus tag - a tagged address is per_client_subaddress, and filing it as shared reports one shared reputation for a client that has its own analytics lane') WHERE NEW."reply_identity_mode" = 'shared_oasis' AND substr (lower (trim (NEW."reply_from_identity")), 1, instr (lower (trim (NEW."reply_from_identity")), '@') - 1) LIKE '%+%';
SELECT RAISE (ABORT, 'per_client_subaddress needs a non-empty plus tag identifying the client, such as support+acmehvac@oasisai.work - without one every client lands in the same undifferentiated stream') WHERE NEW."reply_identity_mode" = 'per_client_subaddress' AND substr (lower (trim (NEW."reply_from_identity")), 1, instr (lower (trim (NEW."reply_from_identity")), '@') - 1) NOT LIKE '%+_%';
SELECT RAISE (ABORT, 'per_client_domain must send from the client own domain, not from oasisai.work - an OASIS address gets none of the reputation isolation this mode is chosen for') WHERE NEW."reply_identity_mode" = 'per_client_domain' AND length (lower (trim (NEW."reply_from_identity"))) > 13 AND substr (lower (trim (NEW."reply_from_identity")), length (lower (trim (NEW."reply_from_identity"))) - 12) IN ('@oasisai.work', '.oasisai.work');
SELECT RAISE (ABORT, 'per_client_domain must send from this profile own website_domain - sending as a third party domain fails SPF alignment and borrows a reputation nobody granted') WHERE NEW."reply_identity_mode" = 'per_client_domain' AND NOT (length (lower (trim (NEW."reply_from_identity"))) > length (lower (trim (NEW."website_domain"))) + 1 AND substr (lower (trim (NEW."reply_from_identity")), length (lower (trim (NEW."reply_from_identity"))) - length (lower (trim (NEW."website_domain")))) IN ('@' || lower (trim (NEW."website_domain")), '.' || lower (trim (NEW."website_domain"))));
END

CREATE TRIGGER "client_automation_profiles_mode_required_on_insert" BEFORE INSERT ON "client_automation_profiles" WHEN NEW."reply_identity_mode" IS NULL BEGIN
