CREATE TRIGGER "client_automation_profiles_mode_required_on_update" BEFORE UPDATE ON "client_automation_profiles" WHEN NEW."reply_identity_mode" IS NULL AND (OLD."reply_identity_mode" IS NOT NULL OR (NEW."status" = 'active' AND OLD."status" <> 'active')) BEGIN
SELECT RAISE (ABORT, 'reply_identity_mode cannot be cleared, and a profile cannot be activated without one');
END

